    '<tr><th>Code</th><th>Name</th><th>Semester</th><th>Credits</th><th>Docs</th><th>Department</th><th>Professor</th><th>Actions</th></tr>' = '<tr><th>@Localizer["Table_Code"]</th><th>@Localizer["Table_Name"]</th><th>@Localizer["Table_Semester"]</th><th>@Localizer["Table_Credits"]</th><th>@Localizer["Table_Docs"]</th><th>@Localizer["Nav_Departments"]</th><th>@Localizer["Table_Professor"]</th><th>@Localizer["Common_Actions"]</th></tr>'
    '<tr><th>Student</th><th>Course</th><th>Date</th><th>Actions</th></tr>' = '<tr><th>@Localizer["Table_Student"]</th><th>@Localizer["Table_Course"]</th><th>@Localizer["Table_Date"]</th><th>@Localizer["Common_Actions"]</th></tr>'
