    '<tr><th>Parent</th><th>Email (login)</th><th>Children</th><th>Login</th><th>Actions</th></tr>' = '<tr><th>@Localizer["Table_Parent"]</th><th>@Localizer["Table_Email"] (@Localizer["Table_Login"])</th><th>@Localizer["Table_Children"]</th><th>@Localizer["Table_Login"]</th><th>@Localizer["Common_Actions"]</th></tr>'
    '<thead><tr><th>Department Name</th><th>Actions</th></tr></thead>' = '<thead><tr><th>@Localizer["Table_DepartmentName"]</th><th>@Localizer["Common_Actions"]</th></tr></thead>'
    '<th>Actions</th>' = '<th>@Localizer["Common_Actions"]</th>'
