    '<span class="um-badge um-badge-green">Yes</span>' = '<span class="um-badge um-badge-green">@Localizer["Common_Yes"]</span>'
    'class="btn btn-light border">Cancel</a>' = 'class="btn btn-light border">@Localizer["Common_Cancel"]</a>'
    'onclick="return confirm(''Reset to default password?'');"' = 'onclick="return confirm(''@Localizer["Msg_ResetPasswordConfirm"]'');"'
    '(string.IsNullOrEmpty(p.Title) ? "Professor" : p.Title)' = '(string.IsNullOrEmpty(p.Title) ? Localizer["Default_ProfessorTitle"].Value : p.Title)'
    '<p class="mb-0">No schedules assigned to your courses yet.</p>' = '<p class="mb-0">@Localizer["Msg_NoSchedules"]</p>'
    'No grades yet.' = '@Localizer["Msg_NoGradesYet"]'
    'No requests yet.' = '@Localizer["Msg_NoRequests"]'
    'Submit request' = '@Localizer["Msg_SubmitRequest"]'
    'Back to list' = '@Localizer["Msg_BackToList"]'
    'Back to dashboard' = '@Localizer["Msg_BackToDashboard"]'
}
$files = Get-ChildItem $viewsPath -Recurse -Filter '*.cshtml'
$n = 0
foreach ($file in $files) {
    $c = [System.IO.File]::ReadAllText($file.FullName)
    $o = $c
    foreach ($k in $replacements.Keys) { $c = $c.Replace($k, $replacements[$k]) }
    if ($c -ne $o) {
        [System.IO.File]::WriteAllText($file.FullName, $c, [System.Text.UTF8Encoding]::new($false))
        $n++
    }
}
Write-Host "Updated $n view files."
